# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">DAILY HABITS vs. CURRENT ACTIONS (PRESENT SIMPLE &amp; CONTINUOUS)</text>\n  <rect x="20" y="45" width="320" height="195" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="180" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">PRESENT SIMPLE (HABITS &amp; ROUTINES)</text>\n  <text x="35" y="94" font-size="11" font-weight="bold" fill="#1e3a8a">• Usage: Daily routines, general truths, permanent states</text>\n  <text x="35" y="116" font-size="11" font-weight="bold" fill="#1e3a8a">• Form: I/You/We/They + V1 | He/She/It + V-s/-es/-ies</text>\n  <text x="35" y="138" font-size="11" font-weight="bold" fill="#1d4ed8">• Frequency Adverbs:</text>\n  <text x="45" y="156" font-size="10.5" fill="#1e40af">always, usually, often, sometimes, rarely/seldom, never</text>\n  <text x="45" y="172" font-size="10.5" fill="#1e40af">every day, on Mondays, twice a week</text>\n  <text x="35" y="196" font-size="10.5" font-weight="bold" fill="#15803d">Ex: "She usually wears casual clothes on weekdays."</text>\n  <text x="35" y="216" font-size="10.5" font-weight="bold" fill="#15803d">Ex: "Do you get up early at weekends?"</text>\n  <rect x="360" y="45" width="320" height="195" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="520" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">PRESENT CONTINUOUS (NOW / TEMPORARY)</text>\n  <text x="375" y="94" font-size="11" font-weight="bold" fill="#14532d">• Usage: Actions happening right now, temporary actions</text>\n  <text x="375" y="116" font-size="11" font-weight="bold" fill="#14532d">• Form: am / is / are + V-ing</text>\n  <text x="375" y="138" font-size="11" font-weight="bold" fill="#166534">• Time Expressions:</text>\n  <text x="385" y="156" font-size="10.5" fill="#14532d">now, right now, at the moment, currently, today, Look!</text>\n  <text x="375" y="178" font-size="10.5" font-weight="bold" fill="#b91c1c">• Stative Verbs (Non-progressive - NO -ing):</text>\n  <text x="385" y="194" font-size="10.5" fill="#991b1b">know, believe, want, need, like, love, hate, belong, own</text>\n  <text x="375" y="216" font-size="10.5" font-weight="bold" fill="#1e40af">Ex: "She is wearing an elegant evening dress right now."</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">FASHION, CLOTHING STYLES &amp; CHARACTER ADJECTIVES</text>\n  <rect x="20" y="45" width="320" height="195" rx="10" fill="#fffbeb" stroke="#d97706" stroke-width="2"/>\n  <text x="180" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#b45309">FASHION, CLOTHING &amp; ACCESSORIES</text>\n  <text x="35" y="94" font-size="11" font-weight="bold" fill="#78350f">• Styles (Giyim Tarzları):</text>\n  <text x="45" y="110" font-size="10.5" fill="#92400e">casual (günlük/rahat), formal/smart (resmi/şık), sporty,</text>\n  <text x="45" y="126" font-size="10.5" fill="#92400e">trendy/fashionable (modaya uygun), old-fashioned (demode)</text>\n  <text x="35" y="150" font-size="11" font-weight="bold" fill="#78350f">• Patterns &amp; Materials (Desen ve Kumaşlar):</text>\n  <text x="45" y="166" font-size="10.5" fill="#92400e">checked (ekose), striped (çizgili), floral (çiçekli), plain (düz);</text>\n  <text x="45" y="182" font-size="10.5" fill="#92400e">cotton (pamuklu), woolen (yünlü), leather (deri), silk (ipek)</text>\n  <text x="35" y="206" font-size="11" font-weight="bold" fill="#78350f">• Verbs: put on (giymek), take off (çıkarmak), try on (denemek),</text>\n  <text x="45" y="222" font-size="10.5" fill="#92400e">fit (bedeni uymak), suit / match (yakışmak / uymak)</text>\n  <rect x="360" y="45" width="320" height="195" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="520" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#7e22ce">DESCRIBING CHARACTER (PERSONALITY)</text>\n  <text x="375" y="94" font-size="11" font-weight="bold" fill="#15803d">• Positive Traits (Olumlu Kişilik Özellikleri):</text>\n  <text x="385" y="112" font-size="10.5" fill="#14532d">generous (cömert), reliable/trustworthy (güvenilir),</text>\n  <text x="385" y="128" font-size="10.5" fill="#14532d">outgoing/sociable (dışa dönük), modest/humble (mütevazı),</text>\n  <text x="385" y="144" font-size="10.5" fill="#14532d">punctual (dakik), patient (sabırlı), polite (kibar)</text>\n  <text x="375" y="170" font-size="11" font-weight="bold" fill="#b91c1c">• Negative Traits (Olumsuz Kişilik Özellikleri):</text>\n  <text x="385" y="188" font-size="10.5" fill="#7f1d1d">stingy/mean (cimri), stubborn (inatçı), arrogant (kibirli),</text>\n  <text x="385" y="204" font-size="10.5" fill="#7f1d1d">jealous (kıskanç), Moody (huysuz), forgetful (unutkan)</text>\n  <text x="375" y="224" font-size="10.5" font-weight="bold" fill="#581c87">Question: "What is he/she like?" (Karakteri nasıldır?)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">COMPARING PEOPLE &amp; OBJECTS: AS...AS, TOO &amp; ENOUGH</text>\n  <rect x="20" y="45" width="320" height="195" rx="10" fill="#ecfeff" stroke="#0891b2" stroke-width="2"/>\n  <text x="180" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#0e7490">COMPARATIVE, SUPERLATIVE &amp; EQUALITY</text>\n  <text x="35" y="94" font-size="11" font-weight="bold" fill="#155e75">• Comparative (2 things): adj-er / more + adj + than</text>\n  <text x="45" y="110" font-size="10.5" fill="#0e7490">"A leather jacket is more expensive than a cotton T-shirt."</text>\n  <text x="35" y="134" font-size="11" font-weight="bold" fill="#155e75">• Superlative (3+ things): the + adj-est / the most + adj</text>\n  <text x="45" y="150" font-size="10.5" fill="#0e7490">"Ali is the most reliable student in our class."</text>\n  <text x="35" y="174" font-size="11" font-weight="bold" fill="#155e75">• Equality: as + adjective + as (kadar ...)</text>\n  <text x="45" y="190" font-size="10.5" fill="#0e7490">"Sneakers are not as formal as leather shoes."</text>\n  <text x="35" y="216" font-size="10.5" font-weight="bold" fill="#b91c1c">Irregular: good→better→the best | bad→worse→the worst</text>\n  <rect x="360" y="45" width="320" height="195" rx="10" fill="#fff1f2" stroke="#e11d48" stroke-width="2"/>\n  <text x="520" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#9f1239">TOO + ADJECTIVE vs. ADJECTIVE + ENOUGH</text>\n  <text x="375" y="96" font-size="11" font-weight="bold" fill="#881337">• too + adjective (aşırı / gereğinden fazla - olumsuz anlam):</text>\n  <text x="385" y="114" font-size="10.5" fill="#9f1239">"This coat is too tight for me." (= I can\'t wear it.)</text>\n  <text x="375" y="142" font-size="11" font-weight="bold" fill="#881337">• (not) + adjective + enough (yeterince ...):</text>\n  <text x="385" y="160" font-size="10.5" fill="#9f1239">"This coat is not big enough for me."</text>\n  <text x="385" y="178" font-size="10.5" fill="#9f1239">"She is old enough to make her own decisions."</text>\n  <text x="375" y="204" font-size="11" font-weight="bold" fill="#15803d">• enough + noun (isimden ÖNCE gelir):</text>\n  <text x="385" y="220" font-size="10.5" fill="#166534">"I don\'t have enough money to buy that designer bag."</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
